class Solution{
    private:
    void markSurroundings(vector<vector<char>> &mat, queue<pair<int,int>>&q, vector<vector<int>> &visited, int n, int m, vector<vector<char>> &ans){

        vector<int>delRows = {-1,0,1,0};
        vector<int>delCols = {0,1,0,-1};

        while(!q.empty()){
            auto fr = q.front();
            q.pop();
            int r1 = fr.first, c1 = fr.second;
            for(int i=0;i<4;i++){
                int r2 = r1 + delRows[i] , c2 = c1 + delCols[i];

                if(r2>=0 && c2>=0 && r2<n && c2<m && mat[r2][c2]=='O' && !visited[r2][c2]){
                    q.push({r2,c2});
                    ans[r2][c2]='O';
                    visited[r2][c2]=1;
                }
            }
        }
    }

public:
    vector<vector<char>> fill(vector<vector<char>> mat) {
       int n = mat.size(), m = mat[0].size();
       vector<vector<int>>visited(n, vector<int>(m,0));
       vector<vector<char>>ans(n, vector<char>(m, 'X'));
       queue<pair<int,int>>q;
       //top and final row
       for(int j=0;j<m;j++){
        if(mat[0][j]=='O') {
            q.push({0,j});
            ans[0][j]='O';
            visited[0][j]=1;
        }
        if(mat[n-1][j]=='O') {
            q.push({n-1,j});
            ans[n-1][j]='O';
            visited[n-1][j]=1;
        }
       }
       //left and right col
       for(int i=0;i<n;i++){
        if(mat[i][0]=='O') {
            q.push({i,0});
            ans[i][0]='O';
            visited[i][0]=1;
        }
        if(mat[i][m-1]=='O') {
            ans[i][m-1]='O';
            q.push({i,m-1});
            visited[i][m-1]=1;
        }
       }
       markSurroundings(mat, q, visited, n, m, ans);
       return ans;
    }
};
