```java[]
class Solution {

    private int[] delRow = {-1, 0, 1, 0};
    private int[] delCol = {0, 1, 0, -1};

    public char[][] fill(char[][] mat) {
        // Determine the dimensions
        int n = mat.length;
        int m = mat[0].length;

        // visited and distance matrix
        boolean[][] visited = new boolean[n][m];
        char[][] newMat = new char[n][m];

        // Traverse the matrix
        for(int i=0; i < n; i++) {
            for(int j=0; j < m; j++) {
                // Border check
                if (i == 0 || i == n - 1 || j == 0 || j == m - 1) {
                    if(mat[i][j] == 'O' && !visited[i][j]){
                        dfsTravel(mat, i, j, visited);
                    }
                } 
            }
        }

        // Traverse the matrix
        for(int i=0; i < n; i++) {
            for(int j=0; j < m; j++) {
                if(mat[i][j] == 'O' && !visited[i][j]){
                    newMat[i][j] = 'X';
                } else{
                    newMat[i][j] = mat[i][j];
                }
            }
        }

        return newMat;
    }

    public void dfsTravel(char[][] mat, int row, int col, boolean[][] visited) {

        visited[row][col] = true;

        // Traverse the 4 neighbors
        for(int i = 0; i < 4; i++) {

            // Coordinates of new cell
            int nRow = row + delRow[i];
            int nCol = col + delCol[i];

            if(isValid(mat, nRow, nCol) && !visited[nRow][nCol]) {
                dfsTravel(mat, nRow, nCol, visited);
            }
        }
    }

    public boolean isValid(char[][] mat, int row, int col) {
        // Traverse the 4 neighbors and validate
        if(
            row >= 0 && 
            col >= 0 && 
            row < mat.length && 
            col < mat[row].length &&
            mat[row][col] == 'O'
        ) {
            return true;
        }
        return false;
    }
}
